def find_first_duplicate(nums):
    """
    Finds the first duplicate element in a given array of integers.
    Returns the first integer that appears more than once.
    Returns -1 if no duplicates are found.
    Raises TypeError if the input is not a list of integers.
    """
    if not isinstance(nums, list):
        raise TypeError("Input must be a list of integers.")

    for item in nums:
        if not isinstance(item, int):
            raise TypeError("All elements in the list must be integers.")

    seen = set()
    for num in nums:
        if num in seen:
            return num
        seen.add(num)
    return -1

