def binomial_coeff(n, k):
    """
    Calculate the binomial coefficient (n choose k).
    """
    if k < 0 or k > n:
        return 0
    if k == 0 or k == n:
        return 1
    if k > n // 2:
        k = n - k

    numerator = 1
    denominator = 1
    for i in range(k):
        numerator *= (n - i)
        denominator *= (i + 1)

    return numerator // denominator

