def min_length_list(lists):
    """
    Finds the list with the minimum length from a list of lists 
    using a lambda function and returns a tuple of (length, list).
    Raises ValueError if the input is not a list of lists.
    """
    if not isinstance(lists, list) or not all(isinstance(item, list) for item in lists):
        raise ValueError('Input must be a list of lists.')

    shortest = min(lists, key=lambda x: len(x))
    return (len(shortest), shortest)

def _validate_input(lists):
    if not isinstance(lists, list) or not all(isinstance(item, list) for item in lists):
